import { readdirSync, readFileSync } from "node:fs";
import { mkdtemp } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { afterEach, describe, expect, it, vi } from "vitest";
import { PROMPT_FILES } from "@/lib/prompts-bundle";

// p5-b4 (QA SF1): a deployed Trigger.dev task has no /prompts folder on disk (trigger.config.ts copies
// only the fonts). Every prompt is embedded in lib/prompts-bundle.ts (generated by
// `npm run prompts:bundle`), so loadPrompt never reads process.cwd(). These tests stop the bundle
// drifting from the Markdown files the owner edits.

const PROMPTS_DIR = path.resolve(process.cwd(), "prompts");
const files = readdirSync(PROMPTS_DIR).filter((f) => f.endsWith(".md")).sort();

afterEach(() => {
  vi.restoreAllMocks();
  vi.resetModules();
});

describe("prompts bundle", () => {
  it("holds every file in /prompts, byte for byte, and nothing else (run `npm run prompts:bundle` after editing a prompt)", () => {
    expect(files.length).toBeGreaterThanOrEqual(10);
    expect(Object.keys(PROMPT_FILES).sort()).toEqual(files);
    for (const file of files) {
      expect([file, PROMPT_FILES[file]]).toEqual([file, readFileSync(path.join(PROMPTS_DIR, file), "utf8")]);
    }
  });

  it("loadPrompt works when process.cwd() is an empty folder (as in a Trigger.dev build) and reads no file", async () => {
    const empty = await mkdtemp(path.join(os.tmpdir(), "no-prompts-"));
    vi.spyOn(process, "cwd").mockReturnValue(empty);
    vi.resetModules();
    const { loadPrompt } = await import("@/lib/prompts");
    for (const file of files) {
      expect([file, loadPrompt(file)]).toEqual([file, readFileSync(path.join(PROMPTS_DIR, file), "utf8").trim()]);
    }
    expect(() => loadPrompt("missing.md")).toThrow(/Unknown prompt/);
    expect(() => loadPrompt("../secrets.md")).toThrow(/Bad prompt file name/);
  });

  it("lib/prompts.ts never reads the disk", () => {
    const src = readFileSync(path.resolve(process.cwd(), "lib/prompts.ts"), "utf8");
    expect(src).not.toMatch(/node:fs|readFileSync|process\.cwd/);
  });
});
